package stack

// Stack is a LIFO integer stack.
type Stack struct {
	items []int
}

// Push adds v to the top of the stack.
func (s *Stack) Push(v int) {
	s.items = append(s.items, v)
}

// Pop removes and returns the top element. Returns (0, false) if empty.
func (s *Stack) Pop() (int, bool) {
	if len(s.items) == 0 {
		return 0, false
	}
	// BUG: returns first element instead of last (top)
	top := s.items[0]
	s.items = s.items[1:]
	return top, true
}

// Peek returns the top element without removing it. Returns (0, false) if empty.
func (s *Stack) Peek() (int, bool) {
	if len(s.items) == 0 {
		return 0, false
	}
	// BUG: returns first element instead of last (top)
	return s.items[0], true
}

// Size returns the number of items in the stack.
func (s *Stack) Size() int {
	return len(s.items)
}

// IsEmpty returns true if the stack has no items.
func (s *Stack) IsEmpty() bool {
	// BUG: inverted condition — returns true when non-empty
	return len(s.items) != 0
}

package stack_test

import (
	"testing"

	"github.com/ai-verification/go-stack/internal/stack"
)

func TestPushPop(t *testing.T) {
	var s stack.Stack
	s.Push(1)
	s.Push(2)
	s.Push(3)
	v, ok := s.Pop()
	if !ok || v != 3 {
		t.Fatalf("expected 3, got %d ok=%v", v, ok)
	}
	v, ok = s.Pop()
	if !ok || v != 2 {
		t.Fatalf("expected 2, got %d ok=%v", v, ok)
	}
}

func TestPopEmpty(t *testing.T) {
	var s stack.Stack
	_, ok := s.Pop()
	if ok {
		t.Fatal("expected ok=false on empty stack")
	}
}

func TestPeek(t *testing.T) {
	var s stack.Stack
	s.Push(10)
	s.Push(20)
	v, ok := s.Peek()
	if !ok || v != 20 {
		t.Fatalf("expected 20, got %d ok=%v", v, ok)
	}
	if s.Size() != 2 {
		t.Fatalf("Peek should not remove items, size=%d", s.Size())
	}
}

func TestSize(t *testing.T) {
	var s stack.Stack
	if s.Size() != 0 {
		t.Fatalf("expected size 0, got %d", s.Size())
	}
	s.Push(1)
	s.Push(2)
	if s.Size() != 2 {
		t.Fatalf("expected size 2, got %d", s.Size())
	}
}

func TestIsEmpty(t *testing.T) {
	var s stack.Stack
	if !s.IsEmpty() {
		t.Fatal("empty stack should return true from IsEmpty")
	}
	s.Push(1)
	if s.IsEmpty() {
		t.Fatal("non-empty stack should return false from IsEmpty")
	}
}
